# Generated by Descant: acceptance tests.

# frozen_string_literal: true

require "rails_helper"

RSpec.describe Timekeeping::AlertSignals do
  it "gathers pending intent ages and stale generation counts per company without mixing companies" do
    now = Time.utc(2026, 3, 3, 12, 10)
    TimekeepingOwnership.ensure_initial!
    InvoiceOperationIntent.create!(company_id: 501, invoice_id: 1, operation_id: SecureRandom.uuid, generation: 1,
                                   state: "pending", created_at: now - 700)
    InvoiceOperationIntent.create!(company_id: 502, invoice_id: 2, operation_id: SecureRandom.uuid, generation: 1,
                                   state: "pending", created_at: now - 60)
    InvoiceOperationIntent.create!(company_id: 502, invoice_id: 3, operation_id: SecureRandom.uuid, generation: 1,
                                   state: "committed", created_at: now - 5000)
    window = lambda do |stale|
      { "window_start" => (now - 300).iso8601, "writes" => 10, "reference_unavailable" => 0,
        "stale_generation" => stale, "latency_ms_sum" => 100, "latency_ms_buckets" => { "25" => 10 } }
    end
    body = {
      "latency_bucket_bounds_ms" => [25, 50, 100, 200, 300, 500, 1000, 2500, 5000],
      "overflow_bucket" => "inf",
      "total_field" => "writes + reference_unavailable",
      "companies" => [
        { "company_id" => 501, "windows" => [window.call(0)] },
        { "company_id" => 502, "windows" => [window.call(2)] }
      ]
    }
    metrics_client = double("metrics client", fetch: body)

    signals = described_class.gather(now:, metrics_client:)

    pending = signals.pending_intent_age_seconds_by_company
    expect(pending.keys).to contain_exactly(501, 502)
    expect(pending.fetch(501)).to be_within(1).of(700)
    expect(pending.fetch(502)).to be_within(1).of(60)
    stale = signals.stale_generation_outside_handoff_by_company
    expect(stale.fetch(502)).to eq(2)
    expect(stale.fetch(501, 0)).to eq(0)
  end
end

RSpec.describe Timekeeping::AlertSignals do
  let(:alert_signals_now) { Time.utc(2026, 3, 3, 12, 7) }
  let(:alert_signals_body) do
    { "latency_bucket_bounds_ms" => [25, 50, 100, 200, 300, 500, 1000, 2500, 5000],
      "overflow_bucket" => "inf",
      "total_field" => "writes + reference_unavailable",
      "companies" => [{ "company_id" => 7, "windows" => [
        { "window_start" => "2026-03-03T12:05:00Z", "writes" => 3, "reference_unavailable" => 0,
          "stale_generation" => 2, "latency_ms_sum" => 30, "latency_ms_buckets" => { "25" => 3 } }
      ] }] }
  end
  let(:alert_signals_client) { instance_double(Timekeeping::MetricsClient, fetch: alert_signals_body) }

  before do
    TimekeepingOwnership.ensure_initial!
    ActiveRecord::Base.connection.execute(ActiveRecord::Base.sanitize_sql_array([
      "INSERT INTO entry_outbox_items (company_id, entry_id, generation, payload, created_at) " \
      "VALUES (7, 1, 1, '{}'::jsonb, ?)", alert_signals_now - 400
    ]))
  end

  it "leaves outbox lag unsourced while Timekeeping owns the entries" do
    TimekeepingOwnership.current.update!(owner: "timekeeping")

    signals = described_class.gather(now: alert_signals_now, metrics_client: alert_signals_client)

    expect(signals.outbox_lag_seconds_by_company).to be_nil
  end

  it "reports no stale generation counts while a handoff step is set" do
    TimekeepingOwnership.current.update!(handoff_step: "freeze")

    signals = described_class.gather(now: alert_signals_now, metrics_client: alert_signals_client)

    expect(signals.stale_generation_outside_handoff_by_company).to eq({})
  end

  it "ignores stale generation counts from windows that started more than 600 seconds ago" do
    windows = alert_signals_body["companies"][0]["windows"]
    windows << windows.first.merge("window_start" => "2026-03-03T11:55:00Z", "stale_generation" => 5)

    signals = described_class.gather(now: alert_signals_now, metrics_client: alert_signals_client)

    expect(signals.stale_generation_outside_handoff_by_company).to eq(7 => 2)
  end

  it "lets a metrics failure propagate instead of building quiet signals" do
    allow(alert_signals_client).to receive(:fetch).and_raise(Timekeeping::MetricsClient::Unavailable, "down")

    expect { described_class.gather(now: alert_signals_now, metrics_client: alert_signals_client) }
      .to raise_error(Timekeeping::MetricsClient::Unavailable)
  end
end
